S=/workspace/nox/web/site; D=/workspace/nox/c300_voice/voice2
echo  | base64 -d > $S/nox-voice-x.js
echo  | base64 -d > $S/nox-voice-x.css
echo  | base64 -d > $D/ru_norm.py
pkill -f tts2_server.py; sleep 1; cd $D; export NOX_VOICE_MODELS=/workspace/nox/voice_models
nohup setsid nice -n 5 /workspace/nox/voice2_venv/bin/python tts2_server.py > /workspace/nox/svc/logs/tts2.log 2>&1 &
cd $S; [ -f voice.html.bak_b_1 ] || cp voice.html voice.html.bak_b_1
python3 - <<'PY'
p="/workspace/nox/web/site/voice.html"; s=open(p,encoding="utf-8").read()
if "nox-voice-x" not in s:
    s=s.replace('<section class="card"><h2>Запись и распознавание','<section class="card" id="vx"></section><section class="card"><h2>Запись и распознавание',1)
    s=s.replace('<h2>Озвучка</h2>','<h2>Озвучка · запасной Piper</h2>',1)
    s=s.replace('<link rel="stylesheet" href="./nox-unify.css">','<link rel="stylesheet" href="./nox-unify.css">\n<link rel="stylesheet" href="./nox-voice-x.css">',1)
    s=s.replace('<script type="module" src="./nox-p-media.js"></script>','<script type="module" src="./nox-p-media.js"></script>\n<script type="module" src="./nox-voice-x.js"></script>',1)
    open(p,"w",encoding="utf-8").write(s); print("patched")
PY
grep -c nox-voice-x voice.html
echo "== shot tools"; grep -n "playwright\|chromium\|screenshot" /workspace/nox/qa_audit.py | head -8 | cut -c1-200
ls /workspace/nox/tools/ms-playwright /workspace/nox/tools/mcp_node 2>/dev/null | head; ls /workspace/nox/tools/node/bin | head
python3 -c "import playwright;print(playwright.__file__)" 2>&1 | tail -1
